"""Original source-inspected Chapter 2 Problems Plus response contracts."""
import gzip,hashlib,json,math,random
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
QUESTIONS=json.loads(gzip.decompress((ROOT/'site/questions/calculus.json.gz').read_bytes()))
SOURCE={q['number']:q for q in QUESTIONS if q['sourceSet']=='chapter-02-problems-plus'}
records={}
def n(label,value,unit='',tolerance=1e-8):return dict(label=label,type='numeric',answer=value,unit=unit,tolerance=tolerance)
def c(label,answer,*wrong):return dict(label=label,type='choice',answer=answer,options=[answer,*wrong])
def add(num,fields,answer,working,why,limited=False):
 q=SOURCE[str(num)];qid=q['id']
 for i,f in enumerate(fields):
  f.update(provenance='original-source-visually-inspected-derived-response',explanation=why,hint='Use the exact source assumptions and part label. Check one-sided limits, parameter signs and interval endpoints.')
  if f['type']=='choice':
   assert len(set(f['options']))==len(f['options'])>1
   random.Random(hashlib.sha256(f'{qid}/{i}'.encode()).hexdigest()).shuffle(f['options'])
   f['selectionPrompt']='Choose the mathematical result or argument for '+f['label']+'.'
 scope='Checks the displayed numeric result or selected mathematical statement; freehand sketches, examples and written proofs are not automatically assessed.'
 grader={**fields[0], 'scope':scope} if len(fields)==1 else dict(type='parts',parts=fields,scope=scope)
 if limited:grader['complete']=False
 records[qid]=dict(grader=grader,fullWorkedSolution=True,status='original-worked-explanation',finalText=answer,steps=[dict(title='Work through the question',equation=working),dict(title='Check the reasoning and conditions',why=why),dict(title='Final answer',calculation=answer)],responsePartPrompt='Use the original textbook exercise above and answer each labeled check below.',objectiveCheckVersion=1,objectiveChecksVerified=True,objectiveFieldCount=len(fields),workedSolutionSource=dict(type='original-derivation-from-user-supplied-textbook',book='Stewart, Calculus: Early Transcendentals, 8th edition',chapter=2,sourceSet=q['sourceSet'],exercise=q['number'],pdfPages=sorted({p['page'] for p in q['parts']}),authoringFile='scripts/calculus-answer-checks/chapter-02/author-problems-plus.py',review='Original chapter PDF local pages 93–94 (printed169–170) rendered and visually inspected, 2026-10-23. Independent algebra, integer cases and limit checks recorded in review-chapters-02-03.json.'))
add(1,[n('Limit',2/3)],'2/3.','Put t=x^(1/6), so x^(1/3)=t² and √x=t³. For x near1 but not1, (t²−1)/(t³−1)=(t+1)/(t²+t+1). Let t→1.','The real-root domain contains a neighborhood of1. Cancellation is only used away from the approach point.')
add(2,[n('a',4),n('b',4)],'a=4, b=4.','A finite two-sided quotient limit requires √b−2=0, so b=4. Rationalization gives (√(ax+4)−2)/x=a/(√(ax+4)+2)→a/4. Set a/4=1.','b<0 has no real neighborhood near0, b=0 has a nonzero limiting numerator, and b>0 other than4 leaves a nonzero constant divided by x. The final pair has a real neighborhood.')
add(3,[n('Limit',-4)],'−4.','For |x|<1/2, 2x−1<0 and 2x+1>0. The numerator is (1−2x)−(2x+1)=−4x, so the quotient is−4 for nonzero x in that interval.','Both sides reduce to the same constant; the absolute-value signs must be resolved before cancellation.')
add(4,[c('Limiting position of Q','(0,1/2).','(0,0).','(0,1).')],'Q→(0,1/2).','Write P=(t,t²), t≠0, and Q=(0,q). Equality of distances QO and QP gives q²=t²+(t²−q)², hence q=(1+t²)/2→1/2.','The equidistance equation directly describes the perpendicular bisector and works for positive or negative t.')
add(5,[c('a · floor(x)/x as x→0','No two-sided limit: the right limit is0 and the left diverges to +∞.','The two-sided limit is0.','The two-sided limit is1.'),n('b · x floor(1/x) as x→0',1)],'(a) Does not exist; right0, left+∞. (b)1.','(a) For0<x<1, floor(x)=0; for−1<x<0, floor(x)=−1, so−1/x→+∞ from the left. (b) Put r=1/x−floor(1/x), where0≤r<1. Then x floor(1/x)=1−xr and |xr|≤|x|→0.','The error bound works for either sign of x, without reversing an inequality incorrectly when multiplying by negative x.')
add(6,[c('a · floor(x)²+floor(y)²=1','Union [m,m+1)×[n,n+1) for (m,n)=(1,0),(−1,0),(0,1),(0,−1).','The full circle x²+y²=1.','Only the four isolated integer points (±1,0),(0,±1).'),c('b · floor(x)²−floor(y)²=3','Union [m,m+1)×[n,n+1) for m=±2 and n=±1, all four combinations.','Union of rectangles for m=±1 and n=±2.','The entire hyperbola x²−y²=3.'),c('c · floor(x+y)²=1','The two strips −1≤x+y<0 and1≤x+y<2.','The strip −1≤x+y<2, including0≤x+y<1.','Only the lines x+y=−1 and x+y=1.'),c('d · floor(x)+floor(y)=1','Union [k,k+1)×[1−k,2−k) for every integer k.','Only the straight line x+y=1.','Union [k,k+1)×[−k,1−k) for every integer k.')],'(a) Four half-open unit squares at integer lower corners (±1,0),(0,±1). (b) Four at (±2,±1). (c)−1≤x+y<0 or1≤x+y<2. (d)⋃k∈ℤ [k,k+1)×[1−k,2−k).','Let m=floor(x), n=floor(y). Each integer pair corresponds to a half-open unit square. (a) m²+n²=1 allows the four unit-axis pairs. (b)(m−n)(m+n)=3 gives m=±2,n=±1. (c)floor(x+y)=±1 gives the stated strips. (d)n=1−m.','Every included lower or left boundary remains closed; every upper or right boundary remains open. These checks recognize the regions, not a submitted sketch.',True)
add(7,[c('All values of a','a=(1−√5)/2 or a=(1+√5)/2.','a=−1 or a=1.','Every real a.')],'a=(1±√5)/2.','The only possible jump is at x=a. Continuity requires left value a+1 equal the right-hand limit a². Solve a²−a−1=0.','Both branches are polynomial on their own sides; matching at the junction is necessary and sufficient.')
add(8,[c('a · Valid example and fixed point','f(x)=1/2 on[0,1], with fixed point c=1/2.','f(x)=2 on[0,1], with fixed point c=2 in the required domain.','f(x)=1−x, with no fixed point.'),c('b · Obstacle to an example without a fixed point','Continuity forces an intersection with y=x.','No obstacle: f(x)=1−x has no fixed point.','The range condition alone forces every x to be fixed.'),c('c · Intermediate Value Theorem argument','h(x)=f(x)−x is continuous; h(0)≥0 and h(1)≤0, so some h(c)=0.','h(x)=f(x)+x is always zero at both endpoints.','Continuity implies f(0)=f(1), so every point is fixed.')],'Every continuous f:[0,1]→[0,1] has a fixed point; one example is f≡1/2 with c=1/2.','Use h=f−identity. Its endpoint signs are opposite or zero, because f(0)≥0 and f(1)≤1. If neither endpoint is zero, the Intermediate Value Theorem supplies an interior zero. A zero h(c)=0 means f(c)=c.','The result needs continuity as well as the self-map range restriction. The checks select one valid example and the argument; they do not assess a new freehand sketch or complete written proof.',True)
add(9,[n('Limit of f(x)g(x)',.75)],'3/4.','Use4fg=(f+g)²−(f−g)². The given limits yield lim fg=(2²−1²)/4=3/4.','The identity uses only the two known combination limits; alternatively derive lim f=3/2 and lim g=1/2.')
add(10,[c('a · Limiting point, with B=(−b,0), C=(b,0)','P→(b/3,0); equivalently MP=BC/6 toward C.','P→M=(0,0).','P→C=(b,0).'),c('b · Locus for altitude h>0, same coordinates','y²=3x²+2bx−b², with b/3<x<b and0<y<2b.','y²=3x²−2bx−b², with−b<x<−b/3.','The line y=x, with x>0.')],'With B=(−b,0), C=(b,0), b>0: limit P=(b/3,0); locus y²=3x²+2bx−b², b/3<x<b, y>0.','Put A=(0,h), s=√(b²+h²). Angle-bisector theorem gives AP/PC=s/(2b). Sectioning AC gives x=bs/(s+2b), y=2bh/(s+2b). As h→0+, s→b, so P→(b/3,0). Eliminate s=2bx/(b−x) and h=by/(b−x) from s²=b²+h² to obtain y²=4x²−(b−x)².','The curve is only the arc with b/3<x<b for positive altitude: the limiting endpoint at zero height is excluded, and y→2b as h→∞. C is the side containing P, so the positive sign in2bx matters. The choice checks the equation/limit, not the sketch.',True)
add(11,[c('a · Antipodal temperature argument','D(θ)=T(θ)−T(θ+π) is continuous and D(θ+π)=−D(θ), so D vanishes somewhere.','The mean temperature forces every antipodal pair to agree.','Continuity alone makes T constant everywhere.'),c('b · Any circle on the surface','Yes, for opposite points on that circle, assuming temperature is continuous around it.','No: the sign-change argument works only on the equator.','Yes, and these points must be antipodal on the entire Earth even on a small latitude circle.'),c('c · Pressure and altitude','The same argument applies to either scalar quantity when its values vary continuously along the circle.','Only temperature can satisfy the argument, regardless of continuity.','It holds for every arbitrary discontinuous assignment of values.')],'The antipodal sign-change argument works for temperature, and for any continuous scalar field on any circle; opposite points on a small circle are opposite relative to that circle.','Parameterize the closed circle with θ modulo2π. Define D(θ)=T(θ)−T(θ+π). Then D(θ+π)=−D(θ). If D(θ)=0, done; otherwise the continuous function has opposite signs half a turn apart, so the Intermediate Value Theorem gives a zero.','For a small circle, opposite points mean diametrically opposite on that circle, not necessarily opposite through the Earth’s center. Pressure/altitude require the analogous continuity hypothesis. A selected argument is not a complete submitted proof.',True)
add(12,[c('Derivative of g(x)=xf(x)','g′(x)=xf′(x)+f(x).','g′(x)=xf′(x).','g′(x)=f(x)f′(x).')],'g′(x)=xf′(x)+f(x).','[g(x+h)−g(x)]/h=x[f(x+h)−f(x)]/h+f(x+h). Differentiability supplies the first limit f′(x) and implies continuity for the second limit f(x).','This derives the product rule for one linear factor directly from the definition rather than assuming the theorem being proved.',True)
add(13,[n('a · f(0)',0),n('b · f′(0)',1),c('c · f′(x)','f′(x)=1+x².','f′(x)=1+2x.','f′(x)=x².')],'(a)0; (b)1; (c)f′(x)=1+x².','Set x=y=0 in the functional equation to get f(0)=2f(0), hence f(0)=0. The supplied limit is then f′(0)=1. Next f(x+h)−f(x)=f(h)+x²h+xh². Divide by h and let h→0 to obtain1+x².','The derivative at a general x follows from the given identity and the single limit at0, not from an unsupported assumption of differentiability everywhere.')
add(14,[n('f(0)',0),n('f′(0)',0)],'f(0)=0 and f′(0)=0.','The bound |f(0)|≤0 forces f(0)=0. For h≠0, |[f(h)−f(0)]/h|=|f(h)|/|h|≤|h|→0. The squeeze theorem gives the derivative0.','The absolute-value bound is valid for both signs of h; it proves differentiability at0 without assuming it in advance.',True)
assert len(records)==14
out=Path(__file__).with_name('problems-plus.json');out.write_text(json.dumps(dict(questions=records),ensure_ascii=False,indent=2)+'\n')
print('authored',len(records),'Problems Plus exercises',sum(r['objectiveFieldCount'] for r in records.values()),'fields')
